import csv
import datetime as dt
from collections import defaultdict
import requests
from math import isnan

STATIONS_FILE = '/root/data/michigan_stations.txt'
OUTPUT_FILE = '/root/output/flood_results.csv'
START = dt.date(2025,4,1)
END = dt.date(2025,4,7)
PARAM = '00060'

with open(STATIONS_FILE) as f:
    stations = [line.strip() for line in f if line.strip()]

# date list inclusive
num_days = (END - START).days + 1
dates = [START + dt.timedelta(days=i) for i in range(num_days)]


def fetch_rdb(url, params):
    resp = requests.get(url, params=params, timeout=60)
    resp.raise_for_status()
    lines = [l for l in resp.text.splitlines() if l and not l.startswith('#')]
    if len(lines) < 2:
        return [], []
    header = lines[0].split('\t')
    rows = []
    for line in lines[2:]:  # skip format line
        if not line or line.startswith('#'):
            continue
        fields = line.split('\t')
        if len(fields) < len(header):
            fields += [''] * (len(header) - len(fields))
        rows.append(dict(zip(header, fields)))
    return header, rows


def pick_value_column(header):
    # pick first column that contains _00060_ and is not a qualifier
    for col in header:
        if f'_{PARAM}_' in col and not col.endswith('_cd'):
            return col
    # fallback: any column that startswith PARAM and not cd
    for col in header:
        if col.startswith(PARAM) and not col.endswith('_cd'):
            return col
    return None


def to_float(val):
    try:
        if val is None:
            return None
        val = val.strip()
        if val == '':
            return None
        return float(val)
    except Exception:
        return None

# Prepare thresholds map: (site, month, day) -> p90
thresholds = {}

# Prepare daily values map: (site, date) -> discharge
values = {}

CHUNK = 20

for i in range(0, len(stations), CHUNK):
    chunk = stations[i:i+CHUNK]

    # Daily values
    dv_header, dv_rows = fetch_rdb(
        'https://waterservices.usgs.gov/nwis/dv/',
        {
            'format': 'rdb',
            'sites': ','.join(chunk),
            'startDT': START.isoformat(),
            'endDT': END.isoformat(),
            'parameterCd': PARAM,
            'siteStatus': 'all',
        },
    )
    val_col = pick_value_column(dv_header) if dv_header else None
    if val_col:
        for row in dv_rows:
            site = row.get('site_no')
            date_str = row.get('datetime')
            val = to_float(row.get(val_col))
            if not site or not date_str or val is None:
                continue
            # date_str may include time
            date_part = date_str.split(' ')[0]
            try:
                date = dt.date.fromisoformat(date_part)
            except ValueError:
                continue
            values[(site, date)] = val

    # Daily statistics (p90)
    stat_header, stat_rows = fetch_rdb(
        'https://waterservices.usgs.gov/nwis/stat/',
        {
            'format': 'rdb',
            'sites': ','.join(chunk),
            'parameterCd': PARAM,
            'statReportType': 'daily',
        },
    )
    if stat_header and 'p90_va' in stat_header:
        for row in stat_rows:
            site = row.get('site_no')
            m = row.get('month_nu')
            d = row.get('day_nu')
            p90 = to_float(row.get('p90_va'))
            if not site or p90 is None:
                continue
            try:
                month = int(m)
                day = int(d)
            except Exception:
                continue
            thresholds[(site, month, day)] = p90

# Count flood days
flood_days = defaultdict(int)

for site in stations:
    count = 0
    for date in dates:
        val = values.get((site, date))
        thr = thresholds.get((site, date.month, date.day))
        if val is None or thr is None:
            continue
        if val >= thr:
            count += 1
    if count > 0:
        flood_days[site] = count

# Write CSV
with open(OUTPUT_FILE, 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for site in sorted(flood_days.keys()):
        writer.writerow([site, flood_days[site]])

print(f"Wrote {OUTPUT_FILE} with {len(flood_days)} stations.")
